import { build } from 'esbuild';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
const built = await build({ entryPoints: ['src/interactive-runtime.js'], bundle: true, minify: true, format: 'iife', globalName: 'GeoDOMInteractive', write: false, legalComments: 'inline', target: ['es2020'] });
const runtimeJs = built.outputFiles[0].text.replace(/\/\/# sourceMappingURL=.*$/gm, '');
const leafletCss = (await readFile('node_modules/leaflet/dist/leaflet.css', 'utf8')).replace(/url\(images\/[^)]+\)/g, 'none');
const runtimeCss = leafletCss + '\n' + await readFile('src/interactive.css', 'utf8');
await writeFile('src/runtime-assets.js', '// Generated by npm run build; edit interactive-runtime.js / interactive.css.\nexport const runtimeJs = ' + JSON.stringify(runtimeJs) + ';\nexport const runtimeCss = ' + JSON.stringify(runtimeCss) + ';\n');
await mkdir('dist', { recursive: true });
await writeFile('dist/interactive-runtime.js', runtimeJs);
await writeFile('dist/interactive.css', runtimeCss);
await writeFile('dist/LEAFLET-LICENSE.txt', await readFile('node_modules/leaflet/LICENSE', 'utf8'));
await build({ entryPoints: ['src/viewer.js'], outfile: 'dist/interactive-viewer.js', bundle: true, minify: true, format: 'esm', legalComments: 'inline', target: ['es2020'] });
console.log('Built portable interactive runtime.');
